//S10: パスワードリセット (期限付き・単回使用トークン) — 標準装備テンプレート
// 原則: トークン実体はメールでのみ送り、DB には SHA-256 ハッシュだけを保存する
// (DB が漏れてもリセットを乗っ取れない)。既定 30 分で失効・1 回使えば無効。
//
// 必要な Prisma モデル:
//   model PasswordResetToken {
//     id        String    @id @default(cuid())
//     userId    String
//     tokenHash String    @unique
//     expiresAt DateTime
//     usedAt    DateTime?
//     createdAt DateTime  @default(now())
//   }
//
// フロー:
//  1) /forgot-password: createResetToken() → tokenHash/expiresAt を保存し、
//     token を URL (https://<app>/reset-password?token=...) としてメール送信。
//     ※ アカウントの存在有無を応答で漏らさない (常に「送信しました」を返す)
//     ※ この API には rate-limit.ts の checkRateLimit を必ず併用する
//  2) /reset-password: hashResetToken(入力 token) で findUnique →
//     isResetTokenValid() なら新パスワード設定 + usedAt 記録 +
//     session-revocation.ts の revokeAllSessions() で全端末ログアウト

import crypto from 'crypto';

export const RESET_TOKEN_TTL_MS = 30 * 60 * 1000; // 30分

export function createResetToken(): { token: string; tokenHash: string; expiresAt: Date } {
  const token = crypto.randomBytes(32).toString('base64url');
  return {
    token,
    tokenHash: hashResetToken(token),
    expiresAt: new Date(Date.now() + RESET_TOKEN_TTL_MS),
  };
}

/** DB 保存・照合は必ずこのハッシュで行う (トークン実体を保存しない) */
export function hashResetToken(token: string): string {
  return crypto.createHash('sha256').update(token).digest('hex');
}

/** 期限内かつ未使用のときのみ有効 */
export function isResetTokenValid(
  record: { expiresAt: Date; usedAt: Date | null } | null,
): boolean {
  if (!record) return false;
  if (record.usedAt) return false;
  return record.expiresAt.getTime() > Date.now();
}
